// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(uint256 ethAmount) public {
        vm.assume(ethAmount > 0 && ethAmount < type(uint256).max / 2);

        address actor = address(0x1234);

        vm.deal(actor, ethAmount);
        vm.prank(actor);
        c.addToBalance{value: ethAmount}();

        uint256 balance = c.getBalance(actor);
        assertTrue(balance > 0);
    }
}
